def value(state, turn):
    """
    state: frozenset of remaining pawn coordinates (tuples)
    turn: 0 for Alice (max), 1 for Bob (min)
    Returns the optimal value from this state
    """
    if not state:
        return 0
    # For current player, try all possible pawns to capture
    if turn == 0:  # Alice maximizing
        return max( dist[(p)] + value(frozenset(state - {p}), 1) for p in state )
    else:           # Bob minimizing
        return min( dist[(p)] + value(frozenset(state - {p}), 0) for p in state )

def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    """
    Computes the optimal total moves Alice can force with perfect play.
    Uses minimax with memoization over sets of remaining pawns.
    """
    dist = precompute_distances(kx, ky, positions)
    # State is a frozenset of pawn positions not yet captured
    initial_state = frozenset( tuple(pos) for pos in positions if pos != [kx, ky] )  # exclude starting pawn if present
    # If the starting position itself is a pawn (should not happen per problem, but allow it)
    if (kx, ky) in set(position for position in positions):
        initial_state = frozenset( p for p in positions if p != [kx, ky] )
    return value(initial_state, 0)

from typing import List

def minimum_shipping_dissatisfaction(n: int, k: int, x: int, order_days: List[int]) -> int:
    dp = [(float('inf'), 0)] * (n + 1)
    dp[0] = (0, 0)  # (min_cost, last_shipment_day)

    for i in range(1, n + 1):
        for j in range(max(0, i - k), i):
            prev_cost, prev_day = dp[j]
            if prev_cost == float('inf'):
                continue
            first_in_batch = order_days[j]
            last_in_batch = order_days[i - 1]
            shipment_day = max(prev_day + x, first_in_batch, last_in_batch)
            batch_cost = 0
            for t in range(j, i):
                batch_cost += shipment_day - order_days[t]
            if batch_cost < dp[i][0] or (batch_cost == dp[i][0] and shipment_day < dp[i][1]):
                dp[i] = (batch_cost, shipment_day)
    return dp[n][0]

